const menu=document.querySelector('.menu-toggle');if(menu){menu.addEventListener('click',()=>{const nav=document.querySelector('.nav');const open=nav.classList.toggle('open');menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Close menu':'Open menu')})}
const filters=document.querySelectorAll('.filter');filters.forEach(button=>button.addEventListener('click',()=>{filters.forEach(x=>x.classList.toggle('active',x===button));const selected=button.dataset.filter;document.querySelectorAll('.listing-grid .trip-card').forEach(card=>{card.hidden=selected!=='all'&&!card.querySelector('.card-type').textContent.includes(selected)})}));
const form=document.querySelector('#enquiry-form');if(form){const params=new URLSearchParams(location.search);const requested=params.get('tour');if(requested){const option=[...form.elements.tour.options].find(x=>x.dataset.slug===requested);if(option)form.elements.tour.value=option.value}form.addEventListener('submit',e=>{e.preventDefault();if(!form.reportValidity())return;const d=new FormData(form),name=String(d.get('name')).trim(),email=String(d.get('email')).trim(),tour=String(d.get('tour')||'Undecided'),travelers=String(d.get('travelers')||'Not specified'),month=String(d.get('month')||'Flexible'),message=String(d.get('message')||'');const body=`Hello Pamir Ecotourism,\n\nI would like to enquire about a journey.\n\nName: ${name}\nEmail: ${email}\nJourney: ${tour}\nTravelers: ${travelers}\nPreferred month: ${month}\n\nMy questions / interests:\n${message}\n\nThank you!`;const link=`mailto:info@pamirecotourism.com?subject=${encodeURIComponent('Pamir journey enquiry — '+tour)}&body=${encodeURIComponent(body)}`;document.querySelector('#form-status').textContent='Your email app is opening. Please press Send there to deliver the enquiry.';location.href=link})}

const currentType=new URLSearchParams(location.search).get('type');if(currentType){const match=[...document.querySelectorAll('.filter')].find(x=>x.dataset.filter===currentType);if(match)match.click()}
